301:         options.metafile = true;
302:       // Suppress direct-eval warnings — Playwright intentionally uses eval
303:       // in evaluate() callbacks that get stringified and sent to the browser.
304:       if (!options.logOverride)
305:         options.logOverride = {};
306:       if (!options.logOverride['direct-eval'])
307:         options.logOverride['direct-eval'] = 'silent';
308:     }
309:     this._options = options;
310:   }
311: 
312:   /** @override */
313:   async run() {
314:     if (watchMode) {
315:       await this._ensureWatching();
316:     } else {
317:       console.log('==== Running esbuild:', this._relativeEntryPoints().join(', '));
318:       const start = Date.now();
319:       const result = await build(this._options);
320:       await this._writeBundleReport(result);
321:       console.log('==== Done in', Date.now() - start, 'ms');
322:     }
323:   }
