325:   async _ensureWatching() {
326:     const start = Date.now();
327:     if (this._context)
328:       return;
329:     this._context = await context(this._options);
330:     disposables.push(() => this._context?.dispose());
331: 
332:     const watcher = chokidar.watch([...this._options.entryPoints, ...(this._watchPaths || [])]);
333:     await new Promise(x => watcher.once('ready', x));
334:     watcher.on('all', () => this._rebuild());
335: 
336:     await this._rebuild();
337:     console.log('==== Esbuild watching:', this._relativeEntryPoints().join(', '), `(started in ${Date.now() - start}ms)`);
