340:   async _rebuild() {
341:     if (this._rebuilding) {
342:       this._sourcesChanged = true;
343:       return;
344:     }
345:     do {
346:       this._sourcesChanged = false;
347:       this._rebuilding = true;
348:       try {
349:         const result = await this._context?.rebuild();
