386: // Single onLoad plugin that does two source-level rewrites:
387: //
388: // 1. `await import('./rel')` → `require('./rel')`. esbuild preserves dynamic
389: //    import() even in CJS format; we want local imports to use require()
390: //    uniformly.
391: //
392: // 2. `import { X } from '@isomorphic/foo'` / `'@utils/bar'` →
393: //    `const { X } = require('playwright-core/lib/coreBundle').iso`
394: //    (same for serverUtils). Per-file esbuild (bundle:false) can't follow
395: //    path aliases to files outside the emitted tree, so we translate these
396: //    at source-load time into coreBundle namespace access. Bundled outputs
397: //    (transform/) use esbuild's `alias` option instead.
398: //
399: // Both rewrites must live in the SAME plugin because esbuild only runs one
400: // onLoad handler per file; the first plugin that returns contents wins.
401: //
402: // 3. `import …  from '<vendored-pkg>'` (debug, mime, ws, …) →
403: //    `const … = require('playwright-core/lib/utilsBundle').<key>` so that
404: //    consumers can write idiomatic npm imports while the runtime still goes
405: //    through the vendored utilsBundle. The mapping lives in
406: //    utils/build/utilsBundleMapping.js.
407: const { MAPPING: VENDORED_MAPPING, VENDORED_PACKAGES } = require('./utilsBundleMapping');
408: 
409: const VENDORED_INVERSE_NAMED = {};
410: for (const [pkg, def] of Object.entries(VENDORED_MAPPING)) {
411:   VENDORED_INVERSE_NAMED[pkg] = {};
412:   if (def.named) {
413:     for (const [srcName, key] of Object.entries(def.named))
414:       VENDORED_INVERSE_NAMED[pkg][srcName] = key;
415:   }
416: }
417: 
418: const VENDORED_PKG_RE = new RegExp(
419:     '^import\\s+(' +
420:     '\\{[^}]*\\}|' +
421:     '\\*\\s+as\\s+\\w+|' +
422:     '\\w+(?:\\s*,\\s*\\{[^}]*\\})?' +
423:     ')\\s+from\\s+\'(' +
424:     [...VENDORED_PACKAGES].map(p => p.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&')).join('|') +
425:     ')\';?',
426:     'gm'
427: );
428: 
429: function _utilsBundleSpecifier(filePath) {
430:   const coreSrcMarker = `${path.sep}playwright-core${path.sep}src${path.sep}`;
431:   const idx = filePath.indexOf(coreSrcMarker);
432:   if (idx === -1)
433:     return "'playwright-core/lib/utilsBundle'";
434:   const coreSrcRoot = filePath.slice(0, idx + coreSrcMarker.length - 1);
435:   let rel = path.relative(path.dirname(filePath), path.join(coreSrcRoot, 'utilsBundle'));
436:   rel = rel.split(path.sep).join('/');
437:   if (!rel.startsWith('.'))
438:     rel = './' + rel;
439:   return `'${rel}'`;
440: }
441: 
442: function _parseClause(clause) {
443:   // Returns { default?: name, namespace?: name, named?: [{src, alias}] }
444:   const out = {};
445:   if (clause.startsWith('{')) {
446:     out.named = _parseNamedList(clause);
447:     return out;
448:   }
449:   if (clause.startsWith('*')) {
450:     out.namespace = clause.match(/\*\s+as\s+(\w+)/)[1];
451:     return out;
452:   }
453:   // default or "default, { named }"
454:   const m = clause.match(/^(\w+)(?:\s*,\s*(\{[^}]*\}))?$/);
455:   if (!m)
456:     return null;
457:   out.default = m[1];
458:   if (m[2])
459:     out.named = _parseNamedList(m[2]);
460:   return out;
461: }
462: 
463: function _parseNamedList(braced) {
464:   const inner = braced.replace(/^\s*\{|\}\s*$/g, '').trim();
465:   if (!inner)
466:     return [];
467:   return inner
468:       .split(',')
469:       .map(s => s.trim())
470:       .filter(Boolean)
471:       // Strip `type` modifier on individual specifiers — type-only imports
472:       // don't need runtime rewriting, but they're often mixed with value
473:       // imports inside a single `{ ... }` clause.
474:       .map(s => s.replace(/^type\s+/, ''))
475:       .map(spec => {
476:         const m = spec.match(/^(\w+)(?:\s+as\s+(\w+))?$/);
477:         if (!m)
478:           return null;
479:         return { src: m[1], alias: m[2] || m[1] };
480:       })
481:       .filter(Boolean);
482: }
483: 
484: function _rewriteVendoredImports(filePath, contents) {
485:   const bundleSpec = _utilsBundleSpecifier(filePath);
486:   return contents.replace(VENDORED_PKG_RE, (full, clause, pkg) => {
487:     const def = VENDORED_MAPPING[pkg];
488:     const parsed = _parseClause(clause);
489:     if (!parsed)
490:       return full;
491:     /** @type {string[]} */
492:     const lines = [];
493:     if (parsed.default && def.default)
494:       lines.push(`const ${parsed.default} = require(${bundleSpec}).${def.default};`);
495:     if (parsed.namespace && def.namespace)
496:       lines.push(`const ${parsed.namespace} = require(${bundleSpec}).${def.namespace};`);
497:     if (parsed.named && def.named) {
498:       const renames = parsed.named.map(({ src, alias }) => {
499:         const key = def.named[src];
500:         if (!key)
501:           return null;
502:         return key === alias ? key : `${key}: ${alias}`;
503:       }).filter(Boolean);
504:       if (renames.length)
505:         lines.push(`const { ${renames.join(', ')} } = require(${bundleSpec});`);
506:     }
507:     return lines.length ? lines.join('\n') : full;
508:   });
509: }
510: 
511: const dynamicImportToRequirePlugin = {
512:   name: 'dynamic-import-to-require',
513:   setup(build) {
514:     build.onLoad({ filter: /\.ts$/ }, async (args) => {
515:       let contents = await fs.promises.readFile(args.path, 'utf8');
516:       const isPlaywrightSrc = args.path.includes(`${path.sep}playwright${path.sep}src${path.sep}`);
517:       const hasAlias = isPlaywrightSrc && (contents.includes("'@isomorphic/") || contents.includes("'@utils/"));
518:       let hasVendored = false;
519:       for (const pkg of VENDORED_PACKAGES) {
520:         if (contents.includes(`'${pkg}'`)) { hasVendored = true; break; }
521:       }
522:       if (!hasAlias && !hasVendored)
523:         return undefined;
524:       // Run vendored rewrites FIRST so that mappings for specific
525:       // `@utils/third_party/*` paths win over the generic `@utils/*`
526:       // alias rewrite below.
527:       if (hasVendored)
528:         contents = _rewriteVendoredImports(args.path, contents);
529:       if (hasAlias) {
530:         contents = contents.replace(
531:             /import\s*\{([^}]*)\}\s*from\s*'@isomorphic\/[^']+';?/g,
532:             (_, names) => `const {${names}} = require('playwright-core/lib/coreBundle').iso;`
533:         );
534:         contents = contents.replace(
535:             /import\s*\{([^}]*)\}\s*from\s*'@utils\/[^']+';?/g,
536:             (_, names) => `const {${names}} = require('playwright-core/lib/coreBundle').utils;`
537:         );
538:       }
539:       return { contents, loader: 'ts' };
540:     });
541:   }
542: };
