38: function addTestCommand(program: Command) {
39:   const command = program.command('test [test-filter...]');
40:   command.description('run tests with Playwright Test');
41:   const options = testOptions.sort((a, b) => a[0].replace(/-/g, '').localeCompare(b[0].replace(/-/g, '')));
42:   options.forEach(([name, { description, choices, preset }]) => {
43:     const option = command.createOption(name, description);
44:     if (choices)
45:       option.choices(choices);
46:     if (preset)
47:       option.preset(preset);
48:     // We don't set the default value here, because we want not specified options to
49:     // fall back to the user config, which we haven't parsed yet.
50:     command.addOption(option);
51:     return command;
52:   });
53:   command.action(async (args, opts) => {
54:     // Args supplied after `--` are appended to the variadic [test-filter...]
55:     // by commander. Strip them so they aren't used as filter regexes; users
56:     // who need to read them go through FullConfig.argv (full process.argv).
57:     const dashDashIndex = process.argv.indexOf('--');
58:     const postDashCount = dashDashIndex >= 0 ? process.argv.length - 1 - dashDashIndex : 0;
59:     const testFilters = args.slice(0, args.length - postDashCount);
60:     try {
61:       await runTests(testFilters, opts);
62:     } catch (e) {
63:       console.error(e);
64:       gracefullyProcessExitDoNotHang(1);
65:     }
66:   });
67:   command.addHelpText('afterAll', `
68: Arguments [test-filter...]:
69:   Pass arguments to filter test files. Each argument is treated as a regular expression. Matching is performed against the absolute file paths.
70: 
71: Examples:
72:   $ npx playwright test my.spec.ts
73:   $ npx playwright test some.spec.ts:42
74:   $ npx playwright test --headed
75:   $ npx playwright test --project=webkit`);
76: }
