126: async function reportMissingDependenciesLinux(packages: string[]) {
127:   // `apt-get install -s` simulates the install: it does not need root and does not
128:   // modify the system. Stdout includes one `Inst <package> ...` line per package
129:   // that would be installed (i.e. that is currently missing).
130:   const { code, stdout, stderr, error } = await spawnAsync('apt-get', ['install', '-s', '--no-install-recommends', ...packages], {});
