132:     throw new Error(`Failed to run 'apt-get install -s' to simulate dependency install: ${error.message}`);
133:   if (code !== 0)
134:     throw new Error(`'apt-get install -s' exited with code ${code}:\n${stderr || stdout}`);
135:   const missingPackages: string[] = [];
136:   for (const line of stdout.split('\n')) {
137:     const match = /^Inst (\S+) /.exec(line);
138:     if (match)
139:       missingPackages.push(match[1]);
